changeSet.sql:
UPDATE actualites SET categorie = 'COMPETITION'   WHERE categorie IN ('COMPETITION');
UPDATE actualites SET categorie = 'FORMATION'     WHERE categorie IN ('ENTRAINEMENT', 'TECHNIQUE', 'SANTE');
UPDATE actualites SET categorie = 'GOUVERNANCE'   WHERE categorie IN ('FEDERATION', 'GOUVERNANCE');
UPDATE actualites SET categorie = 'INFRASTRUCTURE' WHERE categorie IN ('INFRASTRUCTURE', 'INTERNATIONAL');
UPDATE actualites SET categorie = 'GENERAL'       WHERE categorie NOT IN ('COMPETITION','FORMATION','GOUVERNANCE','INFRASTRUCTURE','GENERAL') OR categorie IS NULL;
